AND A.CMPNY_CD = #{cmpnyCd}
AND A.SITE_CD  = #{siteCd}

    AND A.NODE_CD IN

        #{nc}

mapper.select:
/* AppAdminAttdMapper.selectDailyAttdRows */ SELECT A.USER_CD AS userCd , U.USER_NM AS userNm , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, A.NODE_CD) AS nodeNm , A.WORK_YMD AS workYmd , A.WORK_SEQ AS workSeq
/* 차수에 맞춰 정규화한 스케줄 계획시각 (1구간/2구간) */ , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_STR_TIME ELSE SCH.FST_SCH_STR_TIME END AS planStart , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_END_TIME ELSE SCH.FST_SCH_END_TIME END AS planEnd
/* 실제(원본) 출퇴근 일시 — 판정/정산 기준 */ , A.CHECK_IN_DATE AS checkInDate , A.CHECK_IN_TIME AS checkInTime , A.CHECK_OUT_DATE AS checkOutDate , A.CHECK_OUT_TIME AS checkOutTime
/* 외근: 해당 ATTD 의 GPS 행 존재 여부(web attd08 동일 규칙) */ , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G WHERE G.CMPNY_CD = A.CMPNY_CD AND G.ATTD_ID = A.ATTD_ID ) THEN 'Y' ELSE 'N' END AS isOutsideYn
FROM TB_USER_ATTD_MGMT A INNER JOIN TB_USER U ON U.CMPNY_CD = A.CMPNY_CD AND U.USER_CD = A.USER_CD
WHERE A.DEL_YN = 'N' AND A.WORK_YMD = #{workYmd} AND A.WORK_SEQ IN (1, 2)
AND U.USER_NM LIKE CONCAT('%', #{safeKeyword}, '%') ESCAPE '\'
ORDER BY A.USER_CD, A.WORK_SEQ
